```

```tsx
// src/App.tsx
import { Routes, Route, Navigate } from 'react-router-dom';
import HomePage from './pages/HomePage';
import ProductPage from './pages/ProductPage';
import CartPage from './pages/CartPage';
import CheckoutPage from './pages/CheckoutPage';

export default function App() {
  return (
    <Routes>
      <Route path="/" element={<HomePage />} />
      <Route path="/product/:id" element={<ProductPage />} />
      <Route path="/cart" element={<CartPage />} />
      <Route path="/checkout" element={<CheckoutPage />} />
      <Route path="*" element={<Navigate replace to="/" />} />
    </Routes>
  );
}
```

### 2.3 資料取得（SWR + Axios）

```tsx
// src/api/api.ts
import axios from 'axios';

const api = axios.create({
  baseURL: import.meta.env.VITE_API_URL || 'http://localhost:3000',
});

export const fetcher = (url: string) => api.get(url).then(res => res.data);
```

```tsx
// src/hooks/useProducts.ts
import useSWR from 'swr';
import { fetcher } from '../api/api';

export function useProducts() {
  const { data, error } = useSWR('/products', fetcher);
  return {
    products: data,
    isLoading: !error && !data,
    isError: error,
  };
}
```

### 2.4 商品卡片組件

```tsx
// src/components/ProductCard.tsx
import { Link } from 'react-router-dom';
import { Product } from '../types';

interface Props {
  product: Product;
}

export default function ProductCard({ product }: Props) {
  return (
    <Link to={`/product/${product.id}`} className="block p-4 border rounded hover:shadow-lg transition">
      <img src={product.imageUrl} alt={product.name} className="w-full h-48 object-cover rounded" />
      <h3 className="mt-2 font-semibold">{product.name}</h3>
      <p className="text-sm text-gray-600">{product.shortDescription}</p>
      <div className="mt-2 flex justify-between items-center">
        <span className="font-bold">${product.price.toFixed(2)}</span>
        <button className="bg-blue-500 text-white px-3 py-1 rounded hover:bg-blue-600">加入購物車</button>
      </div>
    </Link>
