### 2.5 主頁示例

```tsx
// src/pages/HomePage.tsx
import { useProducts } from '../hooks/useProducts';
import ProductCard from '../components/ProductCard';

export default function HomePage() {
  const { products, isLoading, isError } = useProducts();

  if (isLoading) return <p>載入中…</p>;
  if (isError) return <p>載入失敗，請稍後再試。</p>;

  return (
    <div className="container mx-auto p-4 grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
      {products.map(product => (
        <ProductCard key={product.id} product={product} />
      ))}
    </div>
  );
}
```

### 2.6 購物車（簡易實作）

```tsx
// src/context/CartContext.tsx
import { createContext, useContext, useState, ReactNode } from 'react';
import { Product } from '../types';

interface CartItem extends Product {
  quantity: number;
}

interface CartContextProps {
  items: CartItem[];
  addItem: (product: Product) => void;
  removeItem: (id: string) => void;
  clearCart: () => void;
}

const CartContext = createContext<CartContextProps | undefined>(undefined);

export function CartProvider({ children }: { children: ReactNode }) {
  const [items, setItems] = useState<CartItem[]>([]);

  const addItem = (product: Product) => {
    setItems(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) {
        return prev.map(i =>
          i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeItem = (id: string) => {
    setItems(prev => prev.filter(i => i.id !== id));
  };

  const clearCart = () => setItems([]);

  return (
    <CartContext.Provider value={{ items, addItem, removeItem, clearCart }}>
      {children}
    </CartContext.Provider>
  );
}

export function useCart() {
  const ctx = useContext(CartContext);
  if (!ctx) throw new Error('useCart must be used within CartProvider');
  return ctx;
}
```

```tsx
// src/pages/CartPage.tsx
import { useCart } from '../context/CartContext';

export default function CartPage() {
  const { items, removeItem, clearCart } = useCart();

  const total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);

  return (
    <div className="container mx-auto p-4">
      <h2 className="text-2xl font-semibold mb-4">購物車</h2>
      {items.length === 0 ? (
        <p>購物車空空如也。</p>
      ) : (
        <>
          <ul className="space-y-4">
            {items.map(item => (
              <li key={item.id} className="flex items-center justify-between">
                <div>
                  <h3 className="font-medium">{item.name}</h3>
                  <p className="text-sm text-gray-600">數量：{item.quantity}</p>
                </div>
                <div className="flex items-center space-x-2">
                  <span>${(item.price * item.quantity).toFixed(2)}</span>
                  <button onClick={() => removeItem(item.id)} className="text-red-500">移除</button>
                </div>
              </li>
            ))}
          </ul>
          <div className="mt-6 flex justify-between items-center">
            <span className="font-bold text-xl">總計：${total.toFixed(2)}</span>
            <div>
              <button onClick={clearCart} className="mr-4 bg-gray-200 px-3 py-1 rounded">清空購物車</button>
              <a href="/checkout" className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600">結帳</a>
            </div>
          </div>
        </>
      )}
    </div>
  );
}
```

### 2.7 結帳頁（簡易表單）

```tsx
// src/pages/CheckoutPage.tsx
import { useForm } from 'react-hook-form';
import { useCart } from '../context/CartContext';

interface FormData {
  name: string;
  email: string;
  address: string;
}

export default function CheckoutPage() {
  const { register, handleSubmit, formState: { errors } } = useForm<FormData>();
  const { items, clearCart } = useCart();

  const onSubmit = async (data: FormData) => {
    // 這裡可以呼叫後端 API 處理訂單
    console.log('訂單資料', data, items);
    clearCart();
    alert('訂單已提交！');
  };

  return (
    <div className="container mx-auto p-4 max-w-md">
      <h2 className="text-2xl font-semibold mb-4">結帳</h2>
      <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
        <div>
          <label className="block font-medium mb-1">姓名</label>
          <input {...register('name', { required: true })} className="w-full border rounded p-2" />
          {errors.name && <p className="text-red-500 text-sm">必填欄位</p>}
        </div>
        <div>
          <label className="block font-medium mb-1">電子郵件</label>
          <input {...register('email', { required: true, pattern: /^\S+@\S+$/i })} className="w-full border rounded p-2" />
          {errors.email && <p className="text-red-500 text-sm">請輸入有效的電子郵件</p>}
        </div>
        <div>
          <label className="block font-medium mb-1">送貨地址</label>
          <textarea {...register('address', { required: true })} className="w-full border rounded p-2" rows={3} />
          {errors.address && <p className="text-red-500 text-sm">必填欄位</p>}
        </div>
        <button type="submit" className="w-full bg-blue-500 text-white py-2 rounded hover:bg-blue-600">提交訂單</button>
      </form>
    </div>
  );
}
```

