## 5️⃣ 測試範例

### 5.1 單元測試（Jest + React Testing Library）

```tsx
// src/components/__tests__/ProductCard.test.tsx
import { render, screen } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import ProductCard from '../ProductCard';
import { Product } from '../../types';

const mockProduct: Product = {
  id: '1',
  name: '測試商品',
  shortDescription: '這是一個測試商品',
  price: 99.99,
  imageUrl: '/test.jpg',
};

test('renders product card correctly', () => {
  render(
    <MemoryRouter>
      <ProductCard product={mockProduct} />
    </MemoryRouter>
  );

  expect(screen.getByText('測試商品')).toBeInTheDocument();
  expect(screen.getByText('$99.99')).toBeInTheDocument();
});
```

### 5.2 端到端測試（Cypress）

```js
// cypress/e2e/home.cy.js
describe('Home Page', () => {
  it('should display products', () => {
    cy.intercept('GET', '/products', { fixture: 'products.json' }).as('getProducts');
    cy.visit('/');
    cy.wait('@getProducts');
    cy.get('.product-card').should('have.length.at.least', 1);
  });
});
```

